package main

import (
	"bufio"
	"fmt"
	"os"
)

var s string
var qq = "QAQ"
var arr [][4]int

func Q(m, n int) int {
	if arr[n][m] != -1 {
		return arr[n][m]
	}
	if m == 0 {
		return 1
	}
	if n == 0 {
		return 0
	}
	i, j := 0, 0
	if qq[m-1] == s[n-1] {
		i = Q(m-1, n-1)
	}
	j = Q(m, n-1)
	arr[n][m] = i + j
	return i + j
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		s = scanner.Text()
	}
	arr = make([][4]int, len(s)+1)
	for i := range arr {
		for j := range arr[i] {
			arr[i][j] = -1
		}
	}
	fmt.Println(Q(3, len(s)))
}

